            while (_q.Count == _cap) Monitor.Wait(_gate);   // predicate loop
            _q.Enqueue(item);
            Monitor.PulseAll(_gate);
        }
    }
}

private readonly SemaphoreSlim _gate = new(1, 1);
private readonly SemaphoreSlim _items = new(0, int.MaxValue);
private readonly SemaphoreSlim _space;

public async Task PutAsync(T item, CancellationToken ct = default) {
    await _space.WaitAsync(ct);        // await until there is room
    await _gate.WaitAsync(ct);
    try { _q.Enqueue(item); _items.Release(); }
    finally { _gate.Release(); }
}
